content.content:
  1	/**
  2	 * Salary advance: the one source of truth for money and dates.
  3	 * Screens read from here. They never calculate money or dates themselves.
  4	 *
  5	 * Conventions
  6	 * - Money is whole rupees (integers).
  7	 * - Dates are "YYYY-MM-DD" strings and times are "HH:mm" (local time).
  8	 *   No Date object leaves this module.
  9	 * - `today` is always passed in. There is no hidden clock.
 10	 * - Unknown is null, never 0. An invalid request returns null, never a guess.
 11	 *
 12	 * Sources: PR = PRODUCT_REFERENCE.md, MR = docs/00-my-read.md (Assumptions and principles).
 13	 * "Decided" marks a call made while planning this module.
 14	 */
 15	
 16	// ---- Rules -----------------------------------------------------------------
 17	
 18	export const TIERS = [5000, 10000, 15000]; // PR: loan tiers
 19	export const FEE_PERCENT = 3; // PR: 3% of the amount paid out, charged once
 20	export const COLLECTION_TIME = "18:00"; // MR: payday at 6pm, once salary has landed
 21	export const DEFAULT_AFTER_DAYS = 30; // PR: default at 30+ days past due; day 30 counts
 22	export const NOT_COLLECTED_REASONS = [
 23	  "salary_not_arrived",
 24	  "salary_short",
 25	  "balance_dropped",
 26	  "salary_moved_to_bank",
 27	];
 28	
 29	// Reminders. MR principle 4: at most 2 a week, none between 10pm and 8am.
 30	export const REMINDER_TIME = "10:00";
 31	export const QUIET_HOURS = { from: "22:00", to: "08:00" };
 32	export const MAX_REMINDERS_PER_7_DAYS = 2;
 33	export const REMINDER_DAYS_BEFORE_DUE = 3; // 25 Jul for persona A
 34	export const NOTICE_DAYS_BEFORE_DEFAULT = 7; // 20 Aug for persona A
 35	export const LATE_REMINDER_EVERY_DAYS = 7; // PLACEHOLDER: the cadence isn't decided yet
 36	
 37	export const PROTOTYPE_TODAY = "2026-07-07"; // MR: today is 7 Jul. The year is never shown
 38	
 39	// MR: persona A is paid into NovaPay, persona B into a bank account.
 40	// The 4,250 balance comes from the starter home screen (decided for both).
 41	export const PERSONAS = {
 42	  A: {
 43	    id: "A",
 44	    income_source: "salaried",
 45	    income_verified: true,
 46	    salary_destination: "novapay",
 47	    salary_amount: 68000,
 48	    payday: 28,
 49	    limit: 10000,
 50	    wallet_balance: 4250,
 51	  },
 52	  B: {
 53	    id: "B",
 54	    income_source: "salaried",
 55	    income_verified: false,
 56	    salary_destination: "bank",
 57	    salary_amount: null,
 58	    payday: null,
 59	    limit: null,
 60	    wallet_balance: 4250,
 61	  },
 62	};
 63	
 64	// ---- Date helpers (private) ------------------------------------------------
 65	
 66	const DAY_MS = 24 * 60 * 60 * 1000;
 67	const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
 68	
 69	const pad = (n) => String(n).padStart(2, "0");
 70	
 71	function toUtc(date) {
 72	  const [y, m, d] = date.split("-").map(Number);
 73	  return Date.UTC(y, m - 1, d);
 74	}
 75	
 76	function addDays(date, days) {
 77	  return new Date(toUtc(date) + days * DAY_MS).toISOString().slice(0, 10);
 78	}
 79	
 80	function daysBetween(from, to) {
 81	  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
 82	}
 83	
 84	// The next payday strictly after today. Payday 28 exists in every month.
 85	function nextPayday(payday, today) {
 86	  const [y, m, d] = today.split("-").map(Number);
 87	  const [year, month] = d < payday ? [y, m] : m === 12 ? [y + 1, 1] : [y, m + 1];
 88	  return `${year}-${pad(month)}-${pad(payday)}`;
 89	}
 90	
 91	// ---- Money helpers (private) -----------------------------------------------
 92	
 93	function feeFor(amount) {
 94	  const fee = (amount * FEE_PERCENT) / 100;
 95	  if (!Number.isInteger(fee)) throw new Error(`Fee for ${amount} is not whole rupees`);
 96	  return fee;
 97	}
 98	
 99	// Only events up to and including today count.
100	const upTo = (events, today) => events.filter((e) => e.date <= today);
101	
102	function paidBy(advance, today) {
103	  return upTo(advance.payments, today).reduce((sum, p) => sum + p.amount, 0);
104	}
105	
106	function repaidOn(advance, today) {
107	  let paid = 0;
108	  for (const p of upTo(advance.payments, today)) {
109	    paid += p.amount;
110	    if (paid >= advance.total) return p.date;
111	  }
112	  return null;
113	}
114	
115	function failedAttemptOn(advance, date, today) {
116	  return (
117	    upTo(advance.collection_attempts, today).find(
118	      (a) => a.date === date && a.result === "not_collected"
119	    ) ?? null
120	  );
121	}
122	
123	// ---- Offer, terms, accept --------------------------------------------------
124	
125	export function getOffer(persona, today) {
126	  if (!persona.income_verified || persona.limit == null || persona.payday == null) {
127	    return {
128	      eligibility: "needs_verification",
129	      limit: null,
130	      due_date: null,
131	      days_until_due: null,
132	      collection_time: null,
133	      tiers: null,
134	    };
135	  }
136	  const due_date = nextPayday(persona.payday, today);
137	  return {
138	    eligibility: "eligible",
139	    limit: persona.limit,
140	    due_date,
141	    days_until_due: daysBetween(today, due_date),
142	    collection_time: COLLECTION_TIME, // so the offer screen can say "at 6pm" without reaching for a constant
143	    tiers: TIERS.map((amount) =>
144	      amount <= persona.limit
145	        ? { amount, fee: feeFor(amount), total: amount + feeFor(amount), available: true, blocked_reason: null }
146	        : { amount, fee: null, total: null, available: false, blocked_reason: "over_limit" }
147	    ),
148	  };
149	}
150	
151	function buildTerms({ persona_id, offered_on, applied_amount, disbursed_amount, due_date, reduced_from }) {
152	  const fee = feeFor(disbursed_amount);
153	  const total = disbursed_amount + fee;
154	  const default_date = addDays(due_date, DEFAULT_AFTER_DAYS);
155	  return {
156	    id: `${persona_id}-${offered_on}-${applied_amount}-${disbursed_amount}`,
157	    persona_id,
158	    offered_on,
159	    applied_amount,
160	    disbursed_amount,
161	    fee,
162	    total,
163	    due_date,
164	    collection: { date: due_date, time: COLLECTION_TIME, from: "novapay_wallet" },
165	    default_date,
166	    // MR: the permission ends when repaid or at the default date, whichever comes first.
167	    permission: { amount: total, from_date: due_date, ends_by: default_date },
168	    reduced_from,
169	  };
170	}
171	
172	// Null if the amount isn't a tier, is over the limit, or the persona isn't eligible.
173	export function getTerms(persona, applied_amount, today) {
174	  const offer = getOffer(persona, today);
175	  const tier = offer.tiers?.find((t) => t.amount === applied_amount);
176	  if (!tier || !tier.available) return null;
177	  return buildTerms({
178	    persona_id: persona.id,
179	    offered_on: today,
180	    applied_amount,
181	    disbursed_amount: applied_amount,
182	    due_date: offer.due_date,
183	    reduced_from: null,
184	  });
185	}
186	
187	// MR: a reduced payout always drops to a lower tier, so the fee stays whole.
188	// Null when there's no lower tier (from Rs 5,000): not shown in the prototype.
189	export function reducePayout(terms) {
190	  const lower = TIERS.filter((t) => t < terms.disbursed_amount).pop();
191	  if (lower == null) return null;
192	  return buildTerms({
193	    persona_id: terms.persona_id,
194	    offered_on: terms.offered_on,
195	    applied_amount: terms.applied_amount,
196	    disbursed_amount: lower,
197	    due_date: terms.due_date,
198	    reduced_from: { disbursed_amount: terms.disbursed_amount, fee: terms.fee, total: terms.total },
199	  });
200	}
201	
202	// Accepting the same terms twice returns the same advance, never a second one.
203	const accepted = new Map();
204	
205	export function acceptTerms(terms, { permission_granted }, today) {
206	  if (permission_granted !== true) return { error: "permission_required" };
207	  if (accepted.has(terms.id)) return accepted.get(terms.id);
208	  const advance = {
209	    id: terms.id,
210	    applied_amount: terms.applied_amount,
211	    disbursed_amount: terms.disbursed_amount,
212	    fee: terms.fee,
213	    total: terms.total,
214	    accepted_on: today,
215	    received_on: today, // MR: the payout lands in the wallet when accepted
216	    due_date: terms.due_date,
217	    default_date: terms.default_date,
218	    // What was agreed, kept on the advance so the receipt shows exactly the accepted terms.
219	    collection: terms.collection,
220	    permission: terms.permission,
221	    permission_granted: true,
222	    payments: [],
223	    collection_attempts: [],
224	    payroll_delay_reported_on: null,
225	  };
226	  accepted.set(terms.id, advance);
227	  return advance;
228	}
229	
230	// ---- After accept ----------------------------------------------------------
231	
232	// MR: collection is full amount only, from the NovaPay wallet, once salary has landed.
233	// After payday, it's attempted again only when salary lands (decided, not any incoming money).
234	export function collectionOutcome(advance, { date, time, salary_landed, salary_amount = null, balance, salary_destination = "novapay" }) {
235	  const owed = advance.total - paidBy(advance, date);
236	  if (owed <= 0) return advance;
237	  let reason = null;
238	  if (salary_destination !== "novapay") reason = "salary_moved_to_bank";
239	  else if (!salary_landed) reason = "salary_not_arrived";
240	  else if (balance < owed && salary_amount < owed) reason = "salary_short";
241	  else if (balance < owed) reason = "balance_dropped";
242	  return {
243	    ...advance,
244	    collection_attempts: [
245	      ...advance.collection_attempts,
246	      { date, time, result: reason ? "not_collected" : "collected", reason },
247	    ],
248	    payments: reason ? advance.payments : [...advance.payments, { date, amount: owed, method: "auto" }],
249	  };
250	}
251	
252	// MR: the user can report a payroll delay, and reminders pause. Days late still count.
253	export function reportPayrollDelay(advance, date) {
254	  return { ...advance, payroll_delay_reported_on: advance.payroll_delay_reported_on ?? date };
255	}
256	
257	export function getStatus(advance, today) {
258	  const repaid_on = repaidOn(advance, today);
259	  const attempts = upTo(advance.collection_attempts, today);
260	  const reported = advance.payroll_delay_reported_on;
261	  const common = {
262	    outstanding: advance.total - paidBy(advance, today),
263	    repaid_on,
264	    permission: {
265	      active: repaid_on == null && today < advance.default_date,
266	      ends_on: repaid_on != null && repaid_on < advance.default_date ? repaid_on : advance.default_date,
267	    },
268	    last_attempt: attempts.length ? attempts[attempts.length - 1] : null,
269	    reminders_paused: reported != null && reported <= today,
270	  };
271	
272	  // Days late are counted from the due date and shown truthfully. No grace rule.
273	  if (repaid_on) {
274	    const days_late = Math.max(0, daysBetween(advance.due_date, repaid_on));
275	    const repayment_status = days_late === 0 ? "on_time" : days_late >= DEFAULT_AFTER_DAYS ? "default" : "late";
276	    return { phase: "repaid", repayment_status, days_late, days_until_due: null, days_until_default: null, ...common };
277	  }
278	
279	  const sinceDue = daysBetween(advance.due_date, today);
280	  const days_late = Math.max(0, sinceDue);
281	  let phase;
282	  if (sinceDue < 0) phase = "before_due";
283	  else if (sinceDue === 0) phase = failedAttemptOn(advance, advance.due_date, today) ? "not_collected" : "due_today";
284	  else if (days_late >= DEFAULT_AFTER_DAYS) phase = "default";
285	  else phase = "late";
286	
287	  return {
288	    phase,
289	    repayment_status: phase === "late" || phase === "default" ? phase : null,
290	    days_late,
291	    days_until_due: sinceDue <= 0 ? -sinceDue : null,
292	    days_until_default: phase === "default" ? null : daysBetween(today, advance.default_date),
293	    ...common,
294	  };
295	}
296	
297	// ---- Reminders -------------------------------------------------------------
298	
299	// True if adding `date` keeps every 7-day window at or under the cap.
300	function fitsCap(kept, date) {
301	  for (let start = addDays(date, -6); start <= date; start = addDays(start, 1)) {
302	    const end = addDays(start, 6);
303	    const inWindow = kept.filter((r) => r.date >= start && r.date <= end).length;
304	    if (inWindow >= MAX_REMINDERS_PER_7_DAYS) return false;
305	  }
306	  return true;
307	}
308	
309	// Decided: a material consequence must always be announced, so this is never paused.
310	const NEVER_PAUSED = ["before_default"];
311	
312	/**
313	 * Every reminder for this advance as known today, each with a status:
314	 * "sent" (on or before today), "scheduled" (later, if nothing changes) or "paused".
315	 * Notices about events win over routine late reminders when the 2-a-week cap bites.
316	 * Nothing is sent on or after the default date.
317	 */
318	export function getReminders(advance, today) {
319	  const repaid_on = repaidOn(advance, today);
320	  const owedOn = (date) => repaid_on == null || repaid_on >= date;
321	  const due = advance.due_date;
322	  const failed = failedAttemptOn(advance, due, today);
323	  const lateKnown = failed != null || (today > due && owedOn(due));
324	  const candidates = [];
325	
326	  const beforeDue = addDays(due, -REMINDER_DAYS_BEFORE_DUE);
327	  if (beforeDue >= advance.accepted_on && owedOn(beforeDue)) {
328	    candidates.push({ type: "before_due", date: beforeDue, time: REMINDER_TIME, priority: 1 });
329	  }
330	  if (failed) {
331	    // Sent when the collection fails, not at 10:00: the attempt is at 6pm. Inside 8am–10pm.
332	    candidates.push({ type: "not_collected", date: due, time: failed.time, priority: 0 });
333	  }
334	  if (lateKnown) {
335	    for (let d = addDays(due, LATE_REMINDER_EVERY_DAYS); d < advance.default_date; d = addDays(d, LATE_REMINDER_EVERY_DAYS)) {
336	      if (owedOn(d)) candidates.push({ type: "late", date: d, time: REMINDER_TIME, priority: 2 });
337	    }
338	    const beforeDefault = addDays(advance.default_date, -NOTICE_DAYS_BEFORE_DEFAULT);
339	    if (owedOn(beforeDefault)) {
340	      candidates.push({ type: "before_default", date: beforeDefault, time: REMINDER_TIME, priority: 0 });
341	    }
342	  }
343	
344	  const reported = advance.payroll_delay_reported_on;
345	  const pausedAfter = reported != null && reported <= today ? reported : null;
346	  const kept = [];
347	  const out = [];
348	  candidates.sort((a, b) => a.priority - b.priority || a.date.localeCompare(b.date));
349	  for (const c of candidates) {
350	    if (pausedAfter && c.date > pausedAfter && !NEVER_PAUSED.includes(c.type)) {
351	      out.push({ ...c, status: "paused" });
352	    } else if (fitsCap(kept, c.date)) {
353	      kept.push(c);
354	      out.push({ ...c, status: c.date <= today ? "sent" : "scheduled" });
355	    }
356	  }
357	  return out
358	    .sort((a, b) => a.date.localeCompare(b.date) || a.time.localeCompare(b.time))
359	    .map(({ priority, ...reminder }) => reminder);
360	}
361	
362	// ---- Wallet ----------------------------------------------------------------
363	
364	// Decided: show the real balance, with "Includes Rs X from your advance" beneath it,
365	// on home after accepting only. Spending isn't modelled ("with more time"), so after
366	// the payout day the balance is unknown: null, never a guess. Elsewhere the advance
367	// card reads from the advance itself (disbursed_amount, received_on, total, due_date).
368	export function getWallet(persona, advance, today) {
369	  if (persona.wallet_balance == null) return { balance: null, includes_advance: null };
370	  if (!advance) return { balance: persona.wallet_balance, includes_advance: null };
371	  if (today !== advance.received_on) return { balance: null, includes_advance: null };
372	  return {
373	    balance: persona.wallet_balance + advance.disbursed_amount,
374	    includes_advance: advance.disbursed_amount,
375	  };
376	}
377	
378	// ---- Formatting dates and times --------------------------------------------
379	
380	export function formatDate(date) {
381	  if (date == null) return null;
382	  const [, m, d] = date.split("-").map(Number);
383	  return `${d} ${MONTHS[m - 1]}`;
384	}
385	
386	export function formatTime(time) {
387	  if (time == null) return null;
388	  const [h, min] = time.split(":").map(Number);
389	  const suffix = h < 12 ? "am" : "pm";
390	  const hour = h % 12 || 12;
391	  return min ? `${hour}:${pad(min)}${suffix}` : `${hour}${suffix}`;
392	}
393	
394	// ---- Reviewer scenarios ----------------------------------------------------
395	
396	// The date each state is viewed on. Everything else is 7 Jul.
397	const SCENARIO_DATES = {
398	  S10: "2026-07-25", // reminder before the due date
399	  S11: "2026-07-28", // not collected on payday
400	  S12: "2026-08-02", // late, 5 days
401	  S13: "2026-08-20", // notice before default
402	};
403	
404	// Inputs for each "not collected" cause. Scenario data only; screens don't show these.
405	const NOT_COLLECTED_INPUTS = {
406	  salary_not_arrived: { salary_landed: false, salary_amount: null, balance: 1800, salary_destination: "novapay" },
407	  salary_short: { salary_landed: true, salary_amount: 9000, balance: 9600, salary_destination: "novapay" },
408	  balance_dropped: { salary_landed: true, salary_amount: 68000, balance: 6500, salary_destination: "novapay" },
409	  salary_moved_to_bank: { salary_landed: false, salary_amount: null, balance: 1800, salary_destination: "bank" },
410	};
411	
412	export const SCENARIO_IDS = ["S1", "S2", "S3", "S4", "S5", "S6", "S7", "S8", "S9", "S10", "S11", "S12", "S13"];
413	
414	export function scenario(id, { reason = "salary_not_arrived" } = {}) {
415	  if (!SCENARIO_IDS.includes(id)) throw new Error(`Unknown scenario ${id}`);
416	  const today = SCENARIO_DATES[id] ?? PROTOTYPE_TODAY;
417	  if (id === "S2") {
418	    const B = PERSONAS.B;
419	    return { id, persona: B, today, offer: getOffer(B, today), terms: null, advance: null };
420	  }
421	
422	  const A = PERSONAS.A;
423	  const offer = getOffer(A, PROTOTYPE_TODAY);
424	  const terms = getTerms(A, 10000, PROTOTYPE_TODAY);
425	  const base = { id, persona: A, today, offer, terms, advance: null };
426	  if (["S1", "S3", "S4", "S5", "S6"].includes(id)) return base;
427	  if (id === "S7") return { ...base, terms: reducePayout(terms) };
428	
429	  let advance = acceptTerms(terms, { permission_granted: true }, PROTOTYPE_TODAY);
430	  if (["S11", "S12", "S13"].includes(id)) {
431	    advance = collectionOutcome(advance, {
432	      date: advance.due_date,
433	      time: COLLECTION_TIME,
434	      ...NOT_COLLECTED_INPUTS[reason],
435	    });
436	  }
437	  return { ...base, advance };
438	}

  1	import { useEffect, useRef, useState } from "react";
  2	import ChooseAmount from "./screens/ChooseAmount";
  3	import ReviewAccept from "./screens/ReviewAccept";
  4	import Receipt from "./screens/Receipt";
  5	import Home from "./screens/Home";
  6	import AdvanceDetails from "./screens/AdvanceDetails";
  7	import AcceptOutcome from "./review/AcceptOutcome";
  8	import {
  9	  PERSONAS,
 10	  PROTOTYPE_TODAY,
 11	  acceptTerms,
 12	  getOffer,
 13	  getStatus,
 14	  getTerms,
 15	  getWallet,
 16	  reducePayout,
 17	} from "./advance/salaryAdvance";
 18	
 19	const PROCESSING_MS = 1500; // simulated time to confirm an acceptance
 20	
 21	/**
 22	 * NovaPay prototype in a mobile frame. Screens are built from NovaKit Lite
 23	 * (./novakit) and read every amount and date from the salary-advance module.
 24	 */
 25	
 26	// Mobile frame: a fixed 390×844 device. The AppBar and action area stay put; main scrolls.
 27	// The action area is the sticky bottom of the frame: a screen puts its main action there
 28	// so it stays visible while the content scrolls. Nothing is shown when it's empty.
 29	// `overlay` is for things that sit above the content, like a Toast. It's placed at the
 30	// bottom of the content area, just above the action area, never over the actions.
 31	// `sheet` is for a modal BottomSheet: it covers the whole frame, actions included.
 32	//
 33	// Every screen gets the same arrival: the page title becomes `title`, and after a screen
