    14	const NBSP = " "; // keeps "Rs" and the number on one line
    15	const MINUS = "−"; // a real minus sign, not a hyphen
    16	
    17	const isDev = () => Boolean(import.meta.env?.DEV);
    18	
    19	/**
    20	 * formatAmount(10300)                 -> "Rs 10,300"
    21	 * formatAmount(10000, { sign: "+" })  -> "+Rs 10,000"  (money in)
    22	 * formatAmount(10300, { sign: "-" })  -> "−Rs 10,300"  (money out, real minus)
    23	 * formatAmount(null)                  -> null
    24	 */
    25	export function formatAmount(amount, { sign = null } = {}) {
    26	  if (typeof amount !== "number" || !Number.isFinite(amount)) return null;
    27	  if (isDev() && !Number.isInteger(amount)) {
    28	    console.warn(`formatAmount: ${amount} is not whole rupees. Amounts should come from the salary-advance module.`);
    29	  }
    30	  const out = amount < 0 || sign === "-" || sign === MINUS;
    31	  if (isDev() && amount < 0 && sign === "+") {
    32	    console.warn(`formatAmount: ${amount} is negative but was given sign "+". Showing it as money out.`);
    33	  }
    34	  const prefix = out ? MINUS : sign === "+" ? "+" : "";
    35	  const digits = new Intl.NumberFormat("en-PK").format(Math.abs(amount));
    36	  return `${prefix}Rs${NBSP}${digits}`;
    37	}
